    57  /* Encoding */
    58  struct Encoding0 {
    59    inline bool sanitize (hb_sanitize_context_t *c) const
    60    {
    61      TRACE_SANITIZE (this);
    62      return_trace (c->check_struct (this) && codes[nCodes - 1].sanitize (c));
    63    }
    64
    65    inline hb_codepoint_t get_code (hb_codepoint_t glyph) const
    66    {
    67      assert (glyph > 0);
    68      glyph--;
    69      if (glyph < nCodes)
    70      {
    71        return (hb_codepoint_t)codes[glyph];
    72      }
    73      else
    74        return CFF_UNDEF_CODE;
    75    }
    76
    77    inline unsigned int get_size (void) const
    78    { return HBUINT8::static_size * (nCodes + 1); }
    79
    80    HBUINT8     nCodes;
    81    HBUINT8     codes[VAR];
    82
    83    DEFINE_SIZE_ARRAY(1, codes);
    84  };
