    37  /* Used for writing a temporary charstring */
    38  struct StrEncoder
    39  {
    40    inline StrEncoder (StrBuff &buff_)
    41      : buff (buff_), error (false)
    42    {}
    43
    44    inline void reset (void)
    45    {
    46      buff.resize (0);
    47    }
    48
    49    inline void encode_byte (unsigned char b)
    50    {
    51      if (unlikely (buff.push ((const char)b) == &Crap(char)))
    52        set_error ();
    53    }
    54
    55    inline void encode_int (int v)
    56    {
    57      if ((-1131 <= v) && (v <= 1131))
    58      {
    59        if ((-107 <= v) && (v <= 107))
    60          encode_byte (v + 139);
    61        else if (v > 0)
    62        {
    63          v -= 108;
    64          encode_byte ((v >> 8) + OpCode_TwoBytePosInt0);
    65          encode_byte (v & 0xFF);
    66        }
    67        else
    68        {
    69          v = -v - 108;
    70          encode_byte ((v >> 8) + OpCode_TwoByteNegInt0);
    71          encode_byte (v & 0xFF);
    72        }
    73      }
    74      else
    75      {
    76        if (unlikely (v < -32768))
    77          v = -32768;
    78        else if (unlikely (v > 32767))
    79          v = 32767;
    80        encode_byte (OpCode_shortint);
    81        encode_byte ((v >> 8) & 0xFF);
    82        encode_byte (v & 0xFF);
    83      }
    84    }
    85
    86    inline void encode_num (const Number& n)
    87    {
    88      if (n.in_int_range ())
    89      {
    90        encode_int (n.to_int ());
    91      }
    92      else
    93      {
    94        int32_t v = n.to_fixed ();
    95        encode_byte (OpCode_fixedcs);
    96        encode_byte ((v >> 24) & 0xFF);
    97        encode_byte ((v >> 16) & 0xFF);
    98        encode_byte ((v >> 8) & 0xFF);
    99        encode_byte (v & 0xFF);
   100      }
   101    }
   102
   103    inline void encode_op (OpCode op)
   104    {
   105      if (Is_OpCode_ESC (op))
   106      {
   107        encode_byte (OpCode_escape);
   108        encode_byte (Unmake_OpCode_ESC (op));
   109      }
   110      else
   111        encode_byte (op);
   112    }
   113
   114    inline void copy_str (const ByteStr &str)
   115    {
   116      unsigned int  offset = buff.len;
   117      buff.resize (offset + str.len);
   118      if (unlikely (buff.len < offset + str.len))
   119      {
   120        set_error ();
   121        return;
   122      }
   123      memcpy (&buff[offset], &str.str[0], str.len);
   124    }
   125
   126    inline bool is_error (void) const { return error; }
   127
   128    protected:
   129    inline void set_error (void) { error = true; }
   130
   131    StrBuff &buff;
   132    bool    error;
   133  };
