   162  template <typename OPSTR=OpStr>
   163  struct CFFTopDict_OpSerializer : OpSerializer
   164  {
   165    inline bool serialize (hb_serialize_context_t *c,
   166                           const OPSTR &opstr,
   167                           const CFFSubTableOffsets &offsets) const
   168    {
   169      TRACE_SERIALIZE (this);
   170
   171      switch (opstr.op)
   172      {
   173        case OpCode_CharStrings:
   174          return_trace (FontDict::serialize_offset4_op(c, opstr.op, offsets.charStringsInfo.offset));
   175
   176        case OpCode_FDArray:
   177          return_trace (FontDict::serialize_offset4_op(c, opstr.op, offsets.FDArrayInfo.offset));
   178
   179        case OpCode_FDSelect:
   180          return_trace (FontDict::serialize_offset4_op(c, opstr.op, offsets.FDSelectInfo.offset));
   181
   182        default:
   183          return_trace (copy_opstr (c, opstr));
   184      }
   185      return_trace (true);
   186    }
   187
   188    inline unsigned int calculate_serialized_size (const OPSTR &opstr) const
   189    {
   190      switch (opstr.op)
   191      {
   192        case OpCode_CharStrings:
   193        case OpCode_FDArray:
   194        case OpCode_FDSelect:
   195          return OpCode_Size (OpCode_longintdict) + 4 + OpCode_Size (opstr.op);
   196
   197        default:
   198          return opstr.str.len;
   199      }
   200    }
