   203  struct CFFFontDict_OpSerializer : OpSerializer
   204  {
   205    inline bool serialize (hb_serialize_context_t *c,
   206                           const OpStr &opstr,
   207                           const TableInfo &privateDictInfo) const
   208    {
   209      TRACE_SERIALIZE (this);
   210
   211      if (opstr.op == OpCode_Private)
   212      {
   213        /* serialize the private dict size & offset as 2-byte & 4-byte integers */
   214        if (unlikely (!UnsizedByteStr::serialize_int2 (c, privateDictInfo.size) ||
   215                      !UnsizedByteStr::serialize_int4 (c, privateDictInfo.offset)))
   216          return_trace (false);
   217
   218        /* serialize the opcode */
   219        HBUINT8 *p = c->allocate_size<HBUINT8> (1);
   220        if (unlikely (p == nullptr)) return_trace (false);
   221        p->set (OpCode_Private);
   222
   223        return_trace (true);
   224      }
   225      else
   226      {
   227        HBUINT8 *d = c->allocate_size<HBUINT8> (opstr.str.len);
   228        if (unlikely (d == nullptr)) return_trace (false);
   229        memcpy (d, &opstr.str.str[0], opstr.str.len);
   230      }
   231      return_trace (true);
   232    }
   233
   234    inline unsigned int calculate_serialized_size (const OpStr &opstr) const
   235    {
   236      if (opstr.op == OpCode_Private)
   237        return OpCode_Size (OpCode_longintdict) + 4 + OpCode_Size (OpCode_shortint) + 2 + OpCode_Size (OpCode_Private);
   238      else
   239        return opstr.str.len;
   240    }
