   243  struct CFFPrivateDict_OpSerializer : OpSerializer
   244  {
   245    inline CFFPrivateDict_OpSerializer (bool desubroutinize_, bool drop_hints_)
   246      : desubroutinize (desubroutinize_), drop_hints (drop_hints_) {}
   247
   248    inline bool serialize (hb_serialize_context_t *c,
   249                           const OpStr &opstr,
   250                           const unsigned int subrsOffset) const
   251    {
   252      TRACE_SERIALIZE (this);
   253
   254      if (drop_hints && DictOpSet::is_hint_op (opstr.op))
   255        return true;
   256      if (opstr.op == OpCode_Subrs)
   257      {
   258        if (desubroutinize || (subrsOffset == 0))
   259          return_trace (true);
   260        else
   261          return_trace (FontDict::serialize_offset2_op (c, opstr.op, subrsOffset));
   262      }
   263      else
   264        return_trace (copy_opstr (c, opstr));
   265    }
   266
   267    inline unsigned int calculate_serialized_size (const OpStr &opstr,
   268                                                   bool has_localsubr=true) const
   269    {
   270      if (drop_hints && DictOpSet::is_hint_op (opstr.op))
   271        return 0;
   272      if (opstr.op == OpCode_Subrs)
   273      {
   274        if (desubroutinize || !has_localsubr)
   275          return 0;
   276        else
   277          return OpCode_Size (OpCode_shortint) + 2 + OpCode_Size (opstr.op);
   278      }
   279      else
   280        return opstr.str.len;
